// CodeRaksh Morning Radar Compiler
const today = $now.toISODate();
const num = (v) => Number(String(v ?? '').replace(/[^0-9.-]/g, '')) || 0;
const safeRows = (nodeName) => {
  try { return $(nodeName).all().map(i => i.json).filter(r => Object.keys(r).length); }
  catch(e) { return []; }
};

const bookings = safeRows('Morning - Read Bookings').filter(r => String(r.Start || r.Date || '').startsWith(today));
const allLeads = safeRows('Morning - Read Leads');
const hotLeads = allLeads.filter(r => String(r.Status || '').toLowerCase() === 'hot');
const invoices = safeRows('Morning - Read Invoices');
const unpaidInvoices = invoices.filter(r => String(r.Status || '').toLowerCase() !== 'paid');
const overdueInvoices = unpaidInvoices.filter(r => r['Due date'] && String(r['Due date']) < today);
const dueTodayInvoices = unpaidInvoices.filter(r => r['Due date'] && String(r['Due date']).startsWith(today));

const deadlines = safeRows('Morning - Read Deadlines');
const urgentDeadlines = deadlines.filter(r => {
  if (!r['Due date']) return false;
  const d = String(r['Due date']);
  return d >= today && d <= $now.plus({ days: 3 }).toISODate();
});

const pendingDocs = safeRows('Morning - Read Pending Docs');
const urgentDocs = pendingDocs.filter(r => String(r.Status || '').toLowerCase() === 'pending' && num(r.Reminders) >= 2);

return [{
  json: {
    today_date: today,
    company: "CodeRaksh Company",
    radar: {
      todays_meetings_count: bookings.length,
      todays_meetings: bookings.map(b => `${b.Name || 'Client'} at ${b.Start || b.Time || 'TBD'}`),
